// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (GET /block-kinds)
	ListBlockKinds(ctx context.Context, request ListBlockKindsRequestObject) (ListBlockKindsResponseObject, error)
	// ListExerciseRatings How the user rated their exercises.
	// (GET /exercise-ratings)
	ListExerciseRatings(ctx context.Context, request ListExerciseRatingsRequestObject) (ListExerciseRatingsResponseObject, error)
	// ListExercises The user's exercises with the names of their links.
	// (GET /exercises)
	ListExercises(ctx context.Context, request ListExercisesRequestObject) (ListExercisesResponseObject, error)

	// (POST /exercises)
	CreateExercise(ctx context.Context, request CreateExerciseRequestObject) (CreateExerciseResponseObject, error)
	// GetExercise One exercise with the ids of its links, for the exercise form.
	// (GET /exercises/{id})
	GetExercise(ctx context.Context, request GetExerciseRequestObject) (GetExerciseResponseObject, error)

	// (PUT /exercises/{id})
	UpdateExercise(ctx context.Context, request UpdateExerciseRequestObject) (UpdateExerciseResponseObject, error)
	// RateExercise Rate an exercise 1-5 with notes, replacing an earlier rating.
	// (POST /exercises/{id}/feedback)
	RateExercise(ctx context.Context, request RateExerciseRequestObject) (RateExerciseResponseObject, error)

	// (GET /focuses)
	ListFocuses(ctx context.Context, request ListFocusesRequestObject) (ListFocusesResponseObject, error)

	// (POST /focuses)
	CreateFocus(ctx context.Context, request CreateFocusRequestObject) (CreateFocusResponseObject, error)

	// (GET /joints)
	ListJoints(ctx context.Context, request ListJointsRequestObject) (ListJointsResponseObject, error)

	// (GET /load-units)
	ListLoadUnits(ctx context.Context, request ListLoadUnitsRequestObject) (ListLoadUnitsResponseObject, error)

	// (POST /load-units)
	CreateLoadUnit(ctx context.Context, request CreateLoadUnitRequestObject) (CreateLoadUnitResponseObject, error)

	// (GET /muscle-groups)
	ListMuscleGroups(ctx context.Context, request ListMuscleGroupsRequestObject) (ListMuscleGroupsResponseObject, error)

	// (GET /rep-units)
	ListRepUnits(ctx context.Context, request ListRepUnitsRequestObject) (ListRepUnitsResponseObject, error)

	// (POST /rep-units)
	CreateRepUnit(ctx context.Context, request CreateRepUnitRequestObject) (CreateRepUnitResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListBlockKinds operation middleware
func (sh *strictHandler) ListBlockKinds(w http.ResponseWriter, r *http.Request) {
	var request ListBlockKindsRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListBlockKinds(ctx, request.(ListBlockKindsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListBlockKinds")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListBlockKindsResponseObject); ok {
		if err := validResponse.VisitListBlockKindsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

